def core_recovery_journal(state:Path)->Dict[str,Any]:
    rows=read_jsonl(recovery_ledger_path(state),RECOVERY_LEDGER_SCHEMA)
    prepared={}; committed={}; stale_links=set()
    for r in rows:
        action=r.get('action')
        if action=='CORE_STATE_RECOVERY_PREPARED':
            rid=str(r.get('recovery_id') or '')
            if not rid or rid in prepared: die(f'core recovery journal duplicate/invalid PREPARED id={rid!r}')
            if str(r.get('r11_engine_sha256') or '')!=R11_SHA256 or str(r.get('supervisor_sha256') or '')!=supervisor_sha256():
                die(f'core recovery PREPARED runtime/supervisor pin mismatch id={rid}')
            if str(r.get('core_binary_sha256') or '')!=unpack_meta(state)['core_sha256'] or r.get('active_run_child_lock_confirmed') is not True:
                die(f'core recovery PREPARED authority/core pin mismatch id={rid}')
            prepared[rid]=r
        elif action=='CORE_STATE_RECOVERY_COMMITTED':
            rid=str(r.get('recovery_id') or '')
            if not rid or rid in committed: die(f'core recovery journal duplicate/invalid COMMITTED id={rid!r}')
            if str(r.get('r11_engine_sha256') or '')!=R11_SHA256 or str(r.get('supervisor_sha256') or '')!=supervisor_sha256():
                die(f'core recovery COMMITTED runtime/supervisor pin mismatch id={rid}')
            if str(r.get('core_binary_sha256') or '')!=unpack_meta(state)['core_sha256'] or r.get('active_run_child_lock_confirmed') is not True or r.get('deep_full_hash_verify') is not True:
                die(f'core recovery COMMITTED authority/core verification mismatch id={rid}')
            if int(r.get('before_checkpoint_height',-2))!=int(r.get('after_checkpoint_height',-3)) or str(r.get('before_checkpoint_block_hash') or '')!=str(r.get('after_checkpoint_block_hash') or ''):
                die(f'core recovery COMMITTED checkpoint identity changed id={rid}')
            if int(r.get('script_size_after',-1))!=int(r.get('checkpoint_script_bytes_after',-2)):
                die(f'core recovery COMMITTED scripts/checkpoint mismatch id={rid}')
            committed[rid]=r
        elif action=='STALE_ACTIVE_RUN_RECONCILED' and r.get('core_recovery_record_sha256'):
            stale_links.add(str(r.get('core_recovery_record_sha256')))
    for rid,c in committed.items():
        pr=prepared.get(rid)
        if pr is None: die(f'core recovery COMMITTED has no PREPARED record id={rid}')
        if str(c.get('prepared_record_sha256') or '')!=str(pr.get('record_sha256') or ''):
            die(f'core recovery COMMITTED/PREPARED link mismatch id={rid}')
        for k in ('run_id','run_contract_sha256'):
            if c.get(k)!=pr.get(k): die(f'core recovery journal identity mismatch id={rid} field={k}')
    pending=[r for rid,r in prepared.items() if rid not in committed]
    if len(pending)>1: die(f'multiple pending core recovery intents: {[x.get("recovery_id") for x in pending]}')
    return {'rows':rows,'prepared':prepared,'committed':committed,'pending':pending[0] if pending else None,'stale_links':stale_links}

def prepare_core_recovery_intent(state:Path,authority:Dict[str,Any],before:Dict[str,Any])->Dict[str,Any]:
    if not before.get('recovery_needed'): die('cannot prepare core recovery intent when no physical recovery is required')
    marker=authority['marker']
    if marker.get('phase')!='CHILD_LOCK_CONFIRMED': die('core recovery intent requires confirmed exact-R11 child authority')
    journal=core_recovery_journal(state)
    pending=journal.get('pending')
    if pending is not None:
        if pending.get('run_id')!=marker.get('run_id') or pending.get('run_contract_sha256')!=marker.get('run_contract_sha256'):
            die('pending core recovery intent belongs to a different active run')
        return pending
    mode='DIRTY_FINALIZE_OR_ROLLBACK' if before.get('dirty_present') else 'SCRIPT_SUFFIX_ROLLBACK_WITHOUT_DIRTY'
    rid=uuid.uuid4().hex
    return append_ledger(recovery_ledger_path(state),RECOVERY_LEDGER_SCHEMA,{
        'action':'CORE_STATE_RECOVERY_PREPARED','created_utc':time.strftime('%Y-%m-%dT%H:%M:%SZ',time.gmtime()),
        'recovery_id':rid,'run_id':marker['run_id'],'run_contract_sha256':marker['run_contract_sha256'],
        'recovery_mode_planned':mode,'before_checkpoint_height':before['checkpoint_height'],
        'before_checkpoint_block_hash':before['checkpoint_block_hash'],'dirty_before':before['dirty_present'],
        'script_size_before':before['script_size'],'checkpoint_script_bytes_before':before['checkpoint_script_bytes'],
        'active_run_child_lock_confirmed':True,'r11_engine_sha256':R11_SHA256,
        'core_binary_sha256':validate_core_binary(state)['sha256'],'supervisor_sha256':supervisor_sha256(),
    })

def finalize_core_recovery(state:Path,authority:Dict[str,Any],prepared:Dict[str,Any],core_result:Dict[str,Any])->Dict[str,Any]:
    marker=authority['marker']; journal=core_recovery_journal(state)
    rid=str(prepared.get('recovery_id') or '')
    if rid in journal['committed']:
        return journal['committed'][rid]
    if journal.get('pending') is None or str(journal['pending'].get('record_sha256'))!=str(prepared.get('record_sha256')):
        die('core recovery PREPARED authority changed before COMMITTED publication')
    after=core_result['after']
    if int(after['checkpoint_height'])!=int(prepared.get('before_checkpoint_height')) or str(after['checkpoint_block_hash'])!=str(prepared.get('before_checkpoint_block_hash')):
        die('exact core recovery changed authoritative checkpoint identity')
    if after['dirty_present'] or int(after['script_size'])!=int(after['checkpoint_script_bytes']):
        die('exact core recovery did not leave a clean checkpoint-bound state')
    mode=str(prepared.get('recovery_mode_planned') or '')
    if mode not in ('DIRTY_FINALIZE_OR_ROLLBACK','SCRIPT_SUFFIX_ROLLBACK_WITHOUT_DIRTY'): die('core recovery PREPARED mode invalid')
    return append_ledger(recovery_ledger_path(state),RECOVERY_LEDGER_SCHEMA,{
        'action':'CORE_STATE_RECOVERY_COMMITTED','created_utc':time.strftime('%Y-%m-%dT%H:%M:%SZ',time.gmtime()),
        'recovery_id':rid,'prepared_record_sha256':prepared['record_sha256'],'run_id':marker['run_id'],
        'run_contract_sha256':marker['run_contract_sha256'],'recovery_mode':mode,
        'before_checkpoint_height':prepared['before_checkpoint_height'],'after_checkpoint_height':after['checkpoint_height'],
        'before_checkpoint_block_hash':prepared['before_checkpoint_block_hash'],'after_checkpoint_block_hash':after['checkpoint_block_hash'],
        'dirty_before':prepared['dirty_before'],'script_size_before':prepared['script_size_before'],
        'checkpoint_script_bytes_before':prepared['checkpoint_script_bytes_before'],'script_size_after':after['script_size'],
        'checkpoint_script_bytes_after':after['checkpoint_script_bytes'],'active_run_child_lock_confirmed':True,
        'deep_full_hash_verify':True,'core_binary_sha256':validate_core_binary(state)['sha256'],
        'r11_engine_sha256':R11_SHA256,'supervisor_sha256':supervisor_sha256(),
    })

def resumable_core_recovery(state:Path,authority:Optional[Dict[str,Any]],before:Dict[str,Any])->Tuple[Dict[str,Any],Optional[Dict[str,Any]]]:
    journal=core_recovery_journal(state); pending=journal.get('pending')
    if pending is not None:
        if authority is None or authority['marker'].get('phase')!='CHILD_LOCK_CONFIRMED':
            die('pending physical core recovery exists without confirmed active-run authority')
        if pending.get('run_id')!=authority['marker'].get('run_id') or pending.get('run_contract_sha256')!=authority['marker'].get('run_contract_sha256'):
            die('pending core recovery intent does not match active-run authority')
        cp=unpack_cp(state)
        if int(cp['height'])!=int(pending.get('before_checkpoint_height')) or str(cp['block_hash'])!=str(pending.get('before_checkpoint_block_hash')):
            die('checkpoint changed while a core recovery intent was pending')
        prepared=pending
    elif before.get('recovery_needed'):
        if authority is None or authority['marker'].get('phase')!='CHILD_LOCK_CONFIRMED':
            die('physical V50 recovery requires confirmed active-run authority')
        prepared=prepare_core_recovery_intent(state,authority,before)
    else:
        # No physical mutation is required.  A prior attempt may already have published
        # COMMITTED and crashed before linking it into STALE_ACTIVE_RUN_RECONCILED.
        prior=[]
        if authority is not None:
            prior=[r for r in journal['committed'].values() if r.get('run_id')==authority['marker'].get('run_id') and r.get('run_contract_sha256')==authority['marker'].get('run_contract_sha256')]
            if len(prior)>1: die('multiple committed physical-recovery records belong to the active run')
        result=recover_exact_core_under_driver_exclusion(state)
        return result,(prior[0] if prior else None)
    # PREPARED is durable before State() is allowed to auto-recover.  If a prior attempt
    # already completed the physical operation and crashed before COMMITTED, this call is
    # an idempotent deep verification of the now-clean checkpoint.
    result=recover_exact_core_under_driver_exclusion(state)
    committed=finalize_core_recovery(state,authority,prepared,result)
    return result,committed

def cmd_recover(a):
    state=Path(a.state); engine=ensure_r11_engine(Path(a.r11_engine)); runtime=require_runtime(engine)
    with SupervisorLease(state):
        require_provenance_epoch(state,runtime)
        with R11DriverExclusion(state):
            if active_run_path(state).exists() and upgrade_marker_path(state).exists():
                die('ambiguous dual mutation authority: active run and source upgrade markers coexist; refuse automatic recovery')
            earliest_recovery=core_recovery_preflight(state)
            if earliest_recovery['recovery_needed'] and not active_run_path(state).exists():
                die('physical V50 recovery evidence exists without active-run authority; refuse source-upgrade recovery from opening State() first')
            up=recover_upgrade_if_needed(state,engine)
            # Freeze and validate the active-run authority BEFORE touching dirty state.  The
            # same driver exclusion remains held across exact-core recovery and provenance
            # reconciliation, so no direct R11 mutator can overwrite the lock evidence.
            src=load_source(engine,a.stage_release,a.stage_base,a.source_verify)
            revalidate_bindings(src); verify_runtime_bindings(runtime,engine,True)
            recovery_need=core_recovery_preflight(state)
            pre_authority=None
            journal=core_recovery_journal(state)
            physical_or_pending=bool(recovery_need['recovery_needed'] or journal.get('pending') is not None)
            if active_run_path(state).exists():
                # Any physical/pending recovery requires confirmed authority before State()
                # is opened, because State() itself owns automatic dirty/script recovery.
                pre_authority=load_active_run_authority(state,src,physical_or_pending)
            elif physical_or_pending:
                die('physical/pending V50 recovery exists but no R12 confirmed active-run authority exists; refuse to erase or reinterpret evidence of a possible direct-R11 bypass')
            core_recover,core_recovery_record=resumable_core_recovery(state,pre_authority,recovery_need)
            m,cp=validate_state_files(state); core_ident=validate_core_binary(state); runtime['identities']['core_binary']=core_ident
            if m['source_sha256']!=src['sha256'] or cp['source_sha256']!=src['sha256']:
                die('post-recovery state/source identity mismatch')
            validate_source_lineage_chain(state,m['source_sha256'])
            revalidate_bindings(src); verify_runtime_bindings(runtime,engine,True)
            # pre_authority remains valid because exact-core recovery does not touch the
            # driver-lock file and the exclusion has never been released.
            active_result=recover_active_run_if_needed(state,engine,src,pre_authority,core_recovery_record)
            gate_cleanup={'status':'NONE'}
            if active_result is not None and pre_authority is not None:
                gate_cleanup=cleanup_handoff_stop_gate(Path(a.control),str(pre_authority['marker']['run_id']))
            recon=reconcile_run_provenance(state,engine,src)
            ver=r11_state_cmd(engine,state,['verify','--deep','--full-hash'])
    print(json.dumps({'status':'GREEN','upgrade_recovery':up,'core_recover':core_recover,'core_recovery_record':core_recovery_record,'active_run_recovery':active_result,'handoff_gate_cleanup':gate_cleanup,'provenance_reconciliation':recon,'post_verify':ver},indent=2))

