def cmd_run(a):
    state=Path(a.state); engine=ensure_r11_engine(Path(a.r11_engine)); runtime=require_runtime(engine)
    with SupervisorLease(state):
        if upgrade_marker_path(state).exists(): die('incomplete source upgrade marker present; run recover or upgrade-source first')
        control_preflight(Path(a.control)); stop=safe_stop_path(Path(a.control))
        if stop.exists():
            dst=stop.with_name(f'STOP.consumed.prestart.{int(time.time())}.{os.getpid()}.{uuid.uuid4().hex}')
            os.replace(stop,dst); fsync_dir(stop.parent)
            log(f'CONTROLLED STOP before source hashing; consumed={dst}')
            return 75
        resource_guard(state,Path(a.tmp),float(a.min_state_free_gib),float(a.min_tmp_free_gib),float(a.min_mem_gib))
        pdeathsig_preflight(); src=load_source(engine,a.stage_release,a.stage_base,a.source_verify); source_chain_preflight(src)
        # All existing-state and provenance checks run while direct R11 mutation is excluded.
        # The lock is released only for the deliberate handoff to the exact R11 child; that
        # handoff is then guarded by dirty/ledger/start-height/PREPARE/lock-identity checks.
        with R11DriverExclusion(state) as parent_driver_lease:
            m,cp=validate_state_files(state); core_ident=validate_core_binary(state); runtime['identities']['core_binary']=core_ident; dense_memory_budget_guard(m,a.stage_memory,reserve_gib=12.0)
            verify_runtime_bindings(runtime,engine,True); revalidate_bindings(src)
            if m['source_sha256']!=src['sha256']: die(f'state/source SHA mismatch state={m["source_sha256"]} source={src["sha256"]}; run upgrade-source explicitly')
            if int(a.target_height)>int(src['end_height']): die('target exceeds immutable Stage release')
            anchor=source_block_row(src,int(cp['height'])) if int(cp['height'])>=0 else None
            if anchor and anchor['block_hash']!=cp['block_hash']: die('Stage/source does not match current committed state tip')
            bip30_preflight(src); bitcoin_core_anchor_preflight(a.bitcoin_cli,Path(a.bitcoin_datadir),src,[0,int(cp['height']),int(a.target_height)])
            require_provenance_epoch(state,runtime)
            validate_source_lineage_chain(state,m['source_sha256'])
            recover_active_run_if_needed(state,engine,src)
            # Without a valid active-run marker, any unledgered state advance is a hard bypass, not crash recovery.
            reconcile_run_provenance(state,engine,src)
            handoff_height=int(unpack_cp(state)['height']); handoff_tail,_=apply_ledger_tail(state)
            if handoff_tail!=handoff_height: die('pre-handoff state/provenance synchronization lost')
            rc=run_child(engine,state,src,a,runtime,parent_driver_lease)
        with R11DriverExclusion(state):
            _,final_cp=validate_state_files(state); final_h=int(final_cp['height']); final_tail,_=apply_ledger_tail(state)
            if final_tail!=final_h: die(f'post-run state/provenance mismatch ledger={final_tail} state={final_h}')
            bitcoin_core_anchor_preflight(a.bitcoin_cli,Path(a.bitcoin_datadir),src,[final_h])
            verify_runtime_bindings(runtime,engine,True); revalidate_bindings(src)
        return rc

def cmd_init(a):
    engine=ensure_r11_engine(Path(a.r11_engine)); runtime=require_runtime(engine); state=Path(a.state)
    with SupervisorLease(state):
        control_preflight(Path(a.control)); stop=safe_stop_path(Path(a.control))
        if stop.exists(): die('STOP is active; init is blocked before mutation')
        resource_guard(state,Path(a.tmp),float(a.min_state_free_gib),float(a.min_tmp_free_gib),float(a.min_mem_gib)); pdeathsig_preflight()
        src=load_source(engine,a.stage_release,a.stage_base,a.source_verify); chain=source_chain_preflight(src); bip=bip30_preflight(src)
        bitcoin_core_anchor_preflight(a.bitcoin_cli,Path(a.bitcoin_datadir),src,[0,int(src['end_height'])]); verify_runtime_bindings(runtime,engine,True); revalidate_bindings(src)
        resumed=(state/'state.meta').exists(); r11_output=''
        if not resumed:
            cmd=[str(engine),'--state',str(state),'--tmp',str(a.tmp),'--control',str(a.control)]
            if a.stage_release:cmd+=['--stage-release',str(a.stage_release)]
            else:cmd+=['--stage-base',str(a.stage_base)]
            expected_parent=os.getpid(); cmd+=['init']
            cp=subprocess.run(cmd,text=True,stdout=subprocess.PIPE,stderr=subprocess.PIPE,preexec_fn=lambda:child_pdeathsig(expected_parent))
            if cp.returncode!=0:die(f'R11 init failed: {cp.stderr} {cp.stdout}')
            r11_output=cp.stdout.strip()
        # Crash-idempotent terminalization and post-child handoff are both protected by the
        # driver exclusion. Only the exact empty R11 checkpoint can receive a fresh epoch.
        with R11DriverExclusion(state):
            m,chk=validate_state_files(state); validate_core_binary(state)
            if m['source_sha256']!=src['sha256'] or chk['source_sha256']!=src['sha256']: die('init state/source identity mismatch')
            empty_ok=(int(chk['height'])==-1 and chk['block_hash']=='0'*64 and all(int(chk[k])==0 for k in ('tx_count','out_count','close_count','script_bytes','live_count','live_value_sats')) and [int(x) for x in chk['bip30_seq_plus1']]==[0,0])
            if not empty_ok: die('init terminalization refused: certified-R11 state is not the exact empty checkpoint')
            if read_jsonl(apply_ledger_path(state),APPLY_LEDGER_SCHEMA): die('init terminalization refused: apply provenance already exists')
            if read_jsonl(lineage_path(state),SOURCE_LINEAGE_SCHEMA): die('init terminalization refused: source lineage already exists')
            if active_run_path(state).exists() or upgrade_marker_path(state).exists(): die('init terminalization refused: active mutation authority exists')
            rr=read_jsonl(recovery_ledger_path(state),RECOVERY_LEDGER_SCHEMA)
            if len(rr)>1: die('init terminalization refused: recovery provenance contains post-epoch events')
            if rr: validate_provenance_epoch(state,rr[0],'FRESH_R12_INIT',src['sha256'],None,runtime)
            ver=r11_state_cmd(engine,state,['verify','--deep','--full-hash']); revalidate_bindings(src); verify_runtime_bindings(runtime,engine,True)
            epoch=ensure_provenance_epoch(state,'FRESH_R12_INIT',src['sha256'],None,runtime)
        print(json.dumps({'status':'GREEN','resumed_exact_empty_init':resumed,'r11_init_output':r11_output,'source_chain':chain,'bip30':bip,'provenance_epoch':epoch,'post_verify':ver},indent=2))

def cmd_passthrough(a):
    # Strictly read-only: exact core State() performs automatic dirty recovery, so these
    # commands must exclude every mutating R11 process and reject dirty state before open.
    if a.command not in ('status','verify','fingerprint'):
        die(f'R11 passthrough is read-only in production; forbidden command={a.command!r}')
    if a.command in ('status','fingerprint') and a.extra: die(f'{a.command} passthrough accepts no extra arguments')
    if a.command=='verify' and any(x not in ('--deep','--full-hash') for x in a.extra): die('verify passthrough permits only --deep and --full-hash')
    state=Path(a.state); engine=ensure_r11_engine(Path(a.r11_engine)); require_runtime(engine)
    with SupervisorLease(state), R11DriverExclusion(state):
        validate_state_files(state); validate_core_binary(state)
        out=r11_state_cmd(engine,state,[a.command]+list(a.extra))
    print(json.dumps(out,indent=2))

def parser():
    p=argparse.ArgumentParser(description='MyBot UTXO V50 R12.9 hardened supervisor around exact certified R11 causal engine')
    p.add_argument('--state',default=str(DEFAULT_STATE));p.add_argument('--tmp',default=str(DEFAULT_TMP));p.add_argument('--control',default=str(DEFAULT_CONTROL));p.add_argument('--stage-base',default=str(DEFAULT_LEGACY_STAGE));p.add_argument('--stage-release');p.add_argument('--r11-engine',default=str(DEFAULT_R11_ENGINE),help=argparse.SUPPRESS)
